  /**
   * @displayName Default
   * @validationRule Required for create/update operations
   */
  default1: boolean;
  /**
   * @displayName Request Type Code
   * @validationRule Required for create/update operations
   */
  requestTypeCode: string;
  /**
   * @displayName Service Code
   */
  serviceCode?: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: LifecycleDefinitionStatusKey;
  /**
   * @displayName Version
   * @validationRule Required for create/update operations
   */
